function orderTotal(lines) {
  var subtotal = 0
  for (var i = 0; i < lines.length; i++) {
    subtotal = subtotal + lines[i].price * lines[i].qty
  }
  if (subtotal > 100) {
    var total = 0
    for (var k = 0; k < lines.length; k++) {
      total = total + lines[k].price * lines[k].qty
    }
    return Math.round(total * 0.9 * 100) / 100
  }
  return Math.round(subtotal * 100) / 100
}

