solution.javascript:
function orderTotal(lines) {
  const subtotal = lines.reduce((sum, line) => sum + line.price * line.qty, 0)
  const total = subtotal > 100 ? subtotal * 0.9 : subtotal
  return Math.round(total * 100) / 100
}

